package at.htl.flowstate;

import com.almasb.fxgl.app.scene.Viewport;
import com.almasb.fxgl.core.math.FXGLMath;
import com.almasb.fxgl.dsl.FXGL;
import javafx.geometry.Point2D;
import javafx.scene.media.AudioClip;

import java.net.URL;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;

/**
 * Every sound effect (generated by tools/sound/generate_all.py into /assets/sounds, see tools/sound/PALETTE.md for
 * the dark, heavy palette) with its mix level. The files are peak-normalized, so the volume here is the only place
 * loudness is balanced.
 * <ul>
 *   <li>{@link #play()} for the player and the UI (centred), {@link #at} for things in the world (panned, quieter off screen).</li>
 *   <li>{@link #start()} / {@link #stop()} for sounds that may be cut short (charges, draws, loops).</li>
 *   <li>{@link #ambient} crossfades the background loop (see {@link Ambience}); M toggles {@link #toggleMute() mute}.</li>
 * </ul>
 * Each sound is played at a slightly random pitch so repeats don't sound mechanical, and a sound that is
 * triggered many times in the same instant (a spin hitting five enemies) only plays once. A sound may come in
 * variants (name.wav, name_2.wav, ...): each play picks one, never the same twice in a row. The heavy ones
 * ({@link #DUCKS}) push the background loop down for a moment so they land with more weight.
 */
public enum Sfx {
    // player movement
    JUMP(0.45), LAND(0.35), STEP(0.15, 0.12), DASH(0.6), LEVITATE(0.5), PLAYER_HURT(0.7), PLAYER_DEATH(0.8), FALL(0.6),
    // melee
    SWING_LIGHT(0.5), SWING_HEAVY(0.55), PUNCH(0.35), STAB(0.5), SPIN(0.45),
    HIT_SLASH(0.75), HIT_BLUNT(0.55), HIT_PUNCH(0.5), HIT_ARROW(0.55), HIT_MAGIC(0.65), CRIT(0.45),
    BLOCK_RAISE(0.35), BLOCK_HIT(0.55), DEFLECT(0.6),
    FLOW_UP(0.35, 0), FLOW_MAX(0.5, 0), FLOW_READY(0.16, 0),
    CHARGE_WEAPON(0.4, 0), CHARGE_READY(0.45, 0), PERFECT(0.6, 0),
    SLAM_DIVE(0.45), SLAM_IMPACT(0.65), BOUNCE(0.45),
    // ranged
    BOW_DRAW(0.5, 0.03), BOW_RELEASE(0.65), ARROW_THUNK(0.5), BONE_SHATTER(0.4),
    CRANK(0.35, 0), CROSSBOW_LOADED(0.5), CROSSBOW_FIRE(0.65),
    THROW(0.55), TRIDENT_STICK(0.6), RECALL(0.5), PICKUP(0.4), ENEMY_THROW(0.4),
    // magic
    CAST_ARCANE(0.45), CAST_SPARK(0.45), CAST_ICICLE(0.45), CAST_POISON(0.45), CAST_FIREBALL(0.65), CHARGE_MAGIC(0.45, 0),
    EXPLOSION(0.8), FREEZE(0.55), SHATTER(0.45), CRACKLE(0.22), NO_MANA(0.25, 0.02),
    SHIELD_ON(0.45, 0.02), SHIELD_OFF(0.35, 0.02), SHIELD_HIT(0.35), SHIELD_BREAK(0.6, 0.02),
    ENCHANT_ON(0.35, 0.02), TOGGLE_OFF(0.22, 0.02),
    // enemies, world
    ENEMY_JUMP(0.2), ENEMY_DEATH(0.6), STUN(0.3), CHEST_OPEN(0.6, 0), LEVEL_UP(0.55, 0),
    // demons
    IMP_LEAP(0.4), HOUND_GROWL(0.5), HOUND_LUNGE(0.55), BRUTE_ROAR(0.6), BRUTE_SLAM(0.7), MAGMA_SPLASH(0.55),
    BAT_SCREECH(0.35), CULTIST_CAST(0.45, 0.03), HELLFIRE_LAUNCH(0.5), TELEPORT(0.5),
    FLAIL_SWING(0.45), STONE_CRACK(0.5), WATCHER_CHARGE(0.4, 0.02), BEAM_FIRE(0.6),
    PORTAL_OPEN(0.5), HEX_CAST(0.4), CURSE(0.45, 0.02), BOSS_ROAR(0.9, 0.03), GATE_SLAM(0.8),
    DRAKE_SCREECH(0.55), BOMB_DROP(0.45), VOID_CAST(0.5, 0.02), WELL_OPEN(0.6), WELL_HUM(0.5, 0.02), MIMIC_CHOMP(0.6),
    MATRIARCH_SCREECH(0.8, 0.03), THREAD_TWANG(0.5), THREAD_SNAP(0.55), EGG_HATCH(0.5), SILK_SPIN(0.35), LIGHTS_OUT(0.65, 0),
    ACID_SPIT(0.5), ACID_SIZZLE(0.3),
    HYDRA_ROAR(0.85, 0.03), TAR_SPIT(0.55), TAR_SPLASH(0.5), TAR_WAVE(0.65),
    HOLLOW_RISE(0.8, 0), HOLLOW_ROAR(0.85, 0.03), HOLLOW_STEAL(0.6), HOLLOW_SHARD_PICKUP(0.5), HOLLOW_FLARE(0.7),
    HOLLOW_ECHO(0.5), HOLLOW_SWAP(0.5), HOLLOW_DEATH(0.8, 0),
    HEARTBEAT(0.5, 0.02),
    // UI
    UI_HOVER(0.3, 0.03), UI_CLICK(0.55, 0.03), UI_DENY(0.3, 0), UI_START(0.6, 0), UI_OPEN(0.5, 0.03),
    UI_CLOSE(0.45, 0.03), SKILL_LEARN(0.6, 0), UI_SLOT(0.5, 0.03),
    // ambience (loops)
    AMB_ABYSS(0.4, 0), AMB_MENU(0.35, 0), AMB_LORD(0.35, 0), AMB_MATRIARCH(0.4, 0), AMB_HYDRA(0.35, 0), AMB_HOLLOW(0.4, 0);

    private static final double MASTER = 0.8;
    private static final double DEFAULT_VARIANCE = 0.06;   // +- pitch
    private static final long MIN_GAP_NANOS = 35_000_000L;  // the same sound twice within 35 ms plays once
    private static final double PAN = 0.6;                  // how far to the side a sound at the screen edge goes
    private static final double FADE_DISTANCE = 900;        // off screen, a sound fades out over this many px
    private static final int MAX_VARIANTS = 8;
    /** Heavy sounds: the background loop ducks under them (how far down, for how long). */
    private static final Set<Sfx> DUCKS = EnumSet.of(SLAM_IMPACT, EXPLOSION, BRUTE_SLAM, GATE_SLAM, BOSS_ROAR,
            HYDRA_ROAR, HOLLOW_ROAR, HOLLOW_DEATH, HOLLOW_FLARE, MATRIARCH_SCREECH, TAR_WAVE, LIGHTS_OUT, PLAYER_HURT, PLAYER_DEATH, UI_START, PERFECT, FLOW_MAX);
    private static final double DUCK_DEPTH = 0.55, DUCK_HOLD = 0.35;

    private static boolean muted = false;
    private static Sfx ambient;
    private static double ambientVolume;

    private final double volume;
    private final double variance;
    private AudioClip[] clips;  // the variants
    private AudioClip held;     // separate instance for start()/stop(), so stopping never cuts one-shots
    private boolean missing;    // failed to load once: don't retry (and don't log) every time
    private long lastPlayed;
    private int lastVariant;

    Sfx(double volume) {
        this(volume, DEFAULT_VARIANCE);
    }

    Sfx(double volume, double variance) {
        this.volume = volume;
        this.variance = variance;
    }

    //-----One-shots-----
    public void play() {
        play(1, 1);
    }

    /** @param volume multiplier on the mix level, @param rate pitch/speed multiplier (2 = an octave up) */
    public void play(double volume, double rate) {
        emit(volume, 0, rate);
    }

    /** A sound coming from a point in the world: panned left/right and fading out when far off screen. */
    public void at(Point2D world) {
        at(world, 1, 1);
    }

    public void at(Point2D world, double volume, double rate) {
        Viewport vp = FXGL.getGameScene().getViewport();
        double centre = vp.getX() + vp.getWidth() / 2;
        double dx = world.getX() - centre;
        double outside = Math.max(0, Math.abs(dx) - vp.getWidth() / 2);
        double fade = 1 - Math.min(1, outside / FADE_DISTANCE);
        if (fade <= 0) return;
        double balance = Math.max(-1, Math.min(1, dx / (vp.getWidth() / 2))) * PAN;
        emit(volume * fade, balance, rate);
    }

    private void emit(double vol, double balance, double rate) {
        if (muted || vol <= 0) return;
        long now = System.nanoTime();
        if (now - lastPlayed < MIN_GAP_NANOS) return;
        lastPlayed = now;
        AudioClip c = clip();
        if (c == null) return;
        double r = variance > 0 ? rate * (1 + FXGLMath.random(-variance, variance)) : rate;
        c.play(Math.min(1, volume * vol * MASTER), balance, Math.max(0.125, Math.min(8, r)), 0, 0);
        if (DUCKS.contains(this)) Ambience.duck(DUCK_DEPTH * Math.min(1, vol), DUCK_HOLD);
    }

    //-----Stoppable-----
    /** Plays on its own instance so {@link #stop()} can cut it short (one at a time per sound). */
    public void start() {
        start(false);
    }

    public void start(boolean loop) {
        start(loop, 1);
    }

    /** @param rate speed multiplier, e.g. to make a charge-up sound last exactly as long as the charge */
    public void start(boolean loop, double rate) {
        if (muted) return;
        AudioClip h = held();
        if (h == null) return;
        h.stop();
        h.setCycleCount(loop ? AudioClip.INDEFINITE : 1);
        h.play(Math.min(1, volume * MASTER), 0, Math.max(0.125, Math.min(8, rate)), 0, 0);
    }

    public void stop() {
        if (held != null) held.stop();
    }

    /** Whether the {@link #start()}ed instance is still sounding. */
    public boolean isPlaying() {
        return held != null && held.isPlaying();
    }

    /** Stops every started sound except the ambience (a new game, the main menu). */
    public static void stopStarted() {
        for (Sfx s : values()) if (s != ambient) s.stop();
    }

    //-----Ambience-----
    /** Switches the background loop (null = silence). Starting the one already running does nothing. */
    public static void ambient(Sfx loop) {
        ambient(loop, 1);
    }

    public static void ambient(Sfx loop, double volume) {
        if (loop == ambient && volume == ambientVolume) return;
        ambient = loop;
        ambientVolume = volume;
        if (Ambience.isAvailable()) {
            Ambience.play(loop == null ? null : loop.name().toLowerCase(), loop == null ? 0 : Math.min(1, loop.volume * volume * MASTER));
            return;
        }
        for (Sfx s : values()) if (s.name().startsWith("AMB_")) s.stop();
        if (loop == null || muted) return;
        AudioClip h = loop.held();
        if (h == null) return;
        h.setCycleCount(AudioClip.INDEFINITE);
        h.play(Math.min(1, loop.volume * volume * MASTER));
    }

    //-----Global-----
    /** Low health: the world gets muffled (0 = clear, 1 = barely there). */
    public static void muffle(double amount) {
        Ambience.muffle(amount);
    }

    public static void toggleMute() {
        muted = !muted;
        Ambience.setMuted(muted);
        if (Ambience.isAvailable()) {
            if (muted) for (Sfx s : values()) s.silence();
            return;
        }
        if (muted) {
            for (Sfx s : values()) s.silence();
        } else if (ambient != null) {
            Sfx loop = ambient;
            ambient = null;
            ambient(loop, ambientVolume);
        }
    }

    public static boolean isMuted() {
        return muted;
    }

    /**
     * Decodes every clip up front, the stoppable instances too. Loading one mid-game stalls a frame, and FXGL
     * then runs the next 2 s too fast (see FrameRateLog).
     */
    public static void preload() {
        boolean mixer = Ambience.isAvailable();
        for (Sfx s : values()) {
            boolean loop = s.name().startsWith("AMB_");
            if (loop && mixer) {
                Ambience.preload(s.name().toLowerCase());
                continue;
            }
            s.clip();
            s.held();
        }
    }

    private void silence() {
        stop();
        if (clips != null) for (AudioClip c : clips) c.stop();
    }

    //-----Loading-----
    /** A random variant, never the one played last (when there is more than one). */
    private AudioClip clip() {
        if (clips == null && !missing) clips = loadVariants();
        if (clips == null) return null;
        if (clips.length == 1) return clips[0];
        int pick = FXGLMath.random(0, clips.length - 2);
        if (pick >= lastVariant) pick++;
        lastVariant = pick;
        return clips[pick];
    }

    private AudioClip held() {
        if (held == null && !missing) {
            held = tryLoad(name().toLowerCase(), true);
            if (held == null) missing = true;
        }
        return held;
    }

    private AudioClip[] loadVariants() {
        String base = name().toLowerCase();
        AudioClip first = tryLoad(base, true);
        if (first == null) {
            missing = true;
            return null;
        }
        List<AudioClip> found = new ArrayList<>();
        found.add(first);
        for (int v = 2; v <= MAX_VARIANTS; v++) {
            AudioClip c = tryLoad(base + "_" + v, false);
            if (c == null) break;
            found.add(c);
        }
        return found.toArray(new AudioClip[0]);
    }

    private static AudioClip tryLoad(String name, boolean required) {
        String file = "/assets/sounds/" + name + ".wav";
        URL url = Sfx.class.getResource(file);
        if (url == null) {
            if (required) System.err.println("Missing sound: " + file);
            return null;
        }
        try {
            return new AudioClip(url.toExternalForm());
        } catch (RuntimeException e) {
            // no audio device / media support: the game stays playable, just silent
            System.err.println("Can't load sound " + file + ": " + e.getMessage());
            return null;
        }
    }
}
